@dataclass(frozen=True)
class Task:
  userId: int
  taskId: int
  priority: int

  def __lt__(self, other):
    if self.priority == other.priority:
      return self.taskId > other.taskId
    return self.priority > other.priority


class TaskManager:
  def __init__(self, tasks: list[list[int]]):
    self.taskMap = SortedDict()  # {taskId: Task}, keeps tasks sorted by taskId
    self.taskSet = SortedSet()  # Stores tasks sorted by priority and taskId
    for task in tasks:
      self.add(task[0], task[1], task[2])

  def add(self, userId: int, taskId: int, priority: int) -> None:
    task = Task(userId, taskId, priority)
    self.taskMap[taskId] = task
    self.taskSet.add(task)

  def edit(self, taskId: int, newPriority: int) -> None:
    task = self.taskMap[taskId]
    self.taskSet.remove(task)
    editedTask = Task(task.userId, taskId, newPriority)
    self.taskSet.add(editedTask)
    self.taskMap[taskId] = editedTask

  def rmv(self, taskId: int) -> None:
    task = self.taskMap[taskId]
    self.taskSet.remove(task)
    del self.taskMap[taskId]

  def execTop(self):
    if not self.taskSet:
      return -1
    task = self.taskSet.pop(0)
    del self.taskMap[task.taskId]
    return task.userId

from dataclasses import dataclass


@dataclass(frozen=True)
class T:
  weight: int
  selected: tuple[int]

  def __iter__(self):
    yield self.weight
    yield self.selected


class Solution:
  def maximumWeight(self, intervals: list[list[int]]) -> list[int]:
    intervals = sorted((*interval, i) for i, interval in enumerate(intervals))

    @functools.lru_cache(None)
    def dp(i: int, quota: int) -> T:
      """
      Returns the maximum weight and the selected intervals for intervals[i..n),
      where `quota` is the number of intervals that can be selected.
      """
      if i == len(intervals) or quota == 0:
        return T(0, ())

      skip = dp(i + 1, quota)

      _, r, weight, originalIndex = intervals[i]
      j = bisect.bisect_right(intervals, (r, math.inf))
      nextRes = dp(j, quota - 1)
      pick = T(weight + nextRes.weight,
               sorted((originalIndex, *nextRes.selected)))
      return (pick if (pick.weight > skip.weight or
                       pick.weight == skip.weight and pick.selected < skip.selected)
              else skip)

    return list(dp(0, 4).selected)

class Spreadsheet:
  def __init__(self, rows: int) -> None:
    self.spreadsheet = {}

  def setCell(self, cell: str, value: int) -> None:
    self.spreadsheet[cell] = value

  def resetCell(self, cell: str) -> None:
    self.spreadsheet[cell] = 0

  def getValue(self, formula: str) -> int:
    i = formula.find('+')
    return self._getToken(formula[1:i]) + self._getToken(formula[i+1:])

  def _getToken(self, token: str) -> int:
    return int(token) if token[0].isdigit() else self.spreadsheet.get(token, 0)

class Solution:
  def minEliminationTime(self, timeReq: list[int], splitTime: int) -> int:
    minHeap = timeReq.copy()
    heapq.heapify(minHeap)
    heapq.heappop(minHeap)

    while True:
      bacterial = splitTime + heapq.heappop(minHeap)
      if not minHeap:
        return bacterial
      heapq.heappushpop(minHeap, bacterial)

from dataclasses import dataclass


@dataclass(frozen=True)
class Packet:
  source: int
  destination: int
  timestamp: int


class Router:
  def __init__(self, memoryLimit: int):
    self.memoryLimit = memoryLimit
    self.uniquePackets: set[Packet] = set()
    self.packetQueue: collections.deque[Packet] = collections.deque()
    self.destinationTimestamps = collections.defaultdict(list)
    self.processedPacketIndex = collections.Counter()

  def addPacket(self, source: int, destination: int, timestamp: int) -> bool:
    packet = Packet(source, destination, timestamp)
    if packet in self.uniquePackets:
      return False
    if len(self.packetQueue) == self.memoryLimit:
      self.forwardPacket()
    self.packetQueue.append(packet)
    self.uniquePackets.add(packet)
    if destination not in self.destinationTimestamps:
      self.destinationTimestamps[destination] = []
    self.destinationTimestamps[destination].append(timestamp)
    return True

  def forwardPacket(self) -> list[int]:
    if not self.packetQueue:
      return []
    nextPacket = self.packetQueue.popleft()
    self.uniquePackets.remove(nextPacket)
    self.processedPacketIndex[nextPacket.destination] += 1
    return [nextPacket.source, nextPacket.destination, nextPacket.timestamp]

  def getCount(self, destination: int, startTime: int, endTime: int) -> int:
    if destination not in self.destinationTimestamps:
      return 0
    timestamps = self.destinationTimestamps[destination]
    startIndex = self.processedPacketIndex.get(destination, 0)
    lowerBound = bisect.bisect_left(timestamps, startTime, startIndex)
    upperBound = bisect.bisect_right(timestamps, endTime, startIndex)
    return upperBound - lowerBound

from enum import Enum


class State(Enum):
  FIRST = 0  # first element - add to sum and start product
  SUBTRACT = 1  # second element - subtract from sum and multiply product
  ADD = 2  # third element - add to sum and multiply product


class Solution:
  def maxProduct(self, nums: list[int], k: int, limit: int) -> int:
    MIN = -5000
    if abs(k) > sum(nums):
      return -1

    @functools.lru_cache(None)
    def dp(i: int, product: int, state: State, k: int) -> int:
      if i == len(nums):
        return (product if k == 0 and state != State.FIRST and product <= limit
                else MIN)
      res = dp(i + 1, product, state, k)
      if state == State.FIRST:
        res = max(res, dp(i + 1, nums[i], State.SUBTRACT, k - nums[i]))
      if state == State.SUBTRACT:
        res = max(res, dp(i + 1, min(product * nums[i], limit + 1),
                          State.ADD, k + nums[i]))
      if state == State.ADD:
        res = max(res, dp(i + 1, min(product * nums[i], limit + 1),
                          State.SUBTRACT, k - nums[i]))
      return res

    ans = dp(0, 1, State.FIRST, k)
    return -1 if ans == MIN else ans

class Solution:
  def makeArrayPositive(self, nums: list[int]) -> int:
    MAX = 10**18
    ans = 0
    minSum = nums[0] + nums[1]

    for i in range(2, len(nums)):
      a, b, c = nums[i - 2], nums[i - 1], nums[i]
      minSum = min(minSum + c, a + b + c)
      if minSum <= 0:
        nums[i] = MAX
        minSum = MAX
        ans += 1

    return ans

class Solution:
  def minOperations(self, nums: list[int], k: int) -> int:
    return sum(nums) % k

class Solution:
  def uniqueXorTriplets(self, nums: list[int]) -> int:
